package com.yskj.shopify.web.controller;
import com.alibaba.fastjson.JSONObject;import com.yskj.shopify.web.service.MerchantWebFacadeClient;import com.yskj.shopify.contract.web.MerchantWebProtocol;import com.yskj.shopify.web.security.*;import com.yskj.dao.dto.org.LoginedUser;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpSession;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import org.springframework.util.LinkedMultiValueMap;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class ManualCampaignReceiptControllerTest {
 MockHttpSession session(){var s=new MockHttpSession();var u=new LoginedUser();u.setId("owner");u.setDomainid("org");u.setApplicationid("app");s.setAttribute("logineduser",u);return s;}
 @Test void writesRequireCsrfAndNeverForwardClientSuppliedScope() throws Exception {var client=mock(MerchantWebFacadeClient.class);when(client.exchange(anyString(),any(),anyString(),any(),isNull())).thenReturn(MerchantWebProtocol.json(new JSONObject()));var mvc=MockMvcBuilders.standaloneSetup(new ManualCampaignReceiptController(client,new RemotePageSupport())).build();var s=session();
 mvc.perform(post("/campaigns/detail/receipt-reconciliation").session(s).param("shop","s").param("campaignId","c").param("requestToken","token-1234")).andExpect(status().isForbidden());verifyNoInteractions(client);
 String token=CampaignReceiptCsrf.issue(s,"manual-receipts:org:owner");mvc.perform(post("/campaigns/detail/receipt-reconciliation").session(s).header("X-Campaign-Receipt-Csrf",token).param("shop","s").param("campaignId","c").param("requestToken","token-1234").param("domain","evil.example").param("actorId","evil").param("platformGovernor","true").param("aclNameList","[店铺治理]").param("begin","1")).andExpect(status().isOk());
 var captor=org.mockito.ArgumentCaptor.forClass(JSONObject.class);verify(client).exchange(eq("campaigns.receipt-reconciliation.request"),any(),eq("s"),captor.capture(),isNull());assertThat(captor.getValue().keySet()).containsExactlyInAnyOrder("campaignId","requestToken");}
 @Test void schemaUnavailableIsReturnedAsChineseJsonNotBareInternalServerError()throws Exception{var client=mock(MerchantWebFacadeClient.class);when(client.exchange(anyString(),any(),anyString(),any(),isNull())).thenReturn(MerchantWebProtocol.error("SCHEMA_NOT_READY","补拉任务表尚未初始化，请先执行 V88",503));var mvc=MockMvcBuilders.standaloneSetup(new ManualCampaignReceiptController(client,new RemotePageSupport())).build();mvc.perform(get("/campaigns/detail/receipt-reconciliation/status").session(session()).param("shop","s").param("campaignId","c")).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.message",org.hamcrest.Matchers.containsString("V88")));}
 @Test void previewIssuesAnActorBoundTokenAndDisablesCaching() throws Exception {var client=mock(MerchantWebFacadeClient.class);when(client.exchange(anyString(),any(),anyString(),any(),isNull())).thenReturn(MerchantWebProtocol.json(new JSONObject()));var mvc=MockMvcBuilders.standaloneSetup(new ManualCampaignReceiptController(client,new RemotePageSupport())).build();mvc.perform(get("/campaigns/detail/receipt-reconciliation/preview").session(session()).param("shop","s").param("campaignId","c")).andExpect(status().isOk()).andExpect(header().exists("X-Campaign-Receipt-Csrf")).andExpect(header().string("Cache-Control","no-store"));}
}
